INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33161, 'Malachi 1:8', 'Malachi', 1, 8, 'کله چې تاسو ړاندۀ څاروى د قربانۍ دپاره راولئ، آيا دا غلط کار نۀ دے؟ کله چې تاسو ګوډ يا بيمار څاروى قربانى کوئ، آيا دا غلط کار نۀ دے څۀ؟ کۀ تاسو دا کوشش وکړئ چې دا خپل حکمران ته پېش کړئ، آيا هغه به تاسو نه خوشحاله شى څۀ؟ آيا هغه به تاسو قبول کړى؟“ مالِک خُدائ ربُ الافواج فرمائى.', 'کله چې تاسو راندۀ چاروی د قربانی دپاره راولی، ایا دا غلط کار نۀ دے؟ کله چې تاسو ګود یا بیمار چاروی قربانی کوی، ایا دا غلط کار نۀ دے چۀ؟ کۀ تاسو دا کوشش وکری چې دا خپل حکمران ته پېش کری، ایا هغه به تاسو نه خوشحاله شی چۀ؟ ایا هغه به تاسو قبول کری؟“ مالک خدای رب الافواج فرمایی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Malachi_1_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33162, 'Malachi 1:9', 'Malachi', 1, 9, '”اوس خُدائ پاک ته سوال زارى کوئ چې په مونږ مهربان شى. ستاسو نه په داسې قربانۍ پېش کولو، آيا هغه به تاسو قبول کړى؟“ مالِک خُدائ ربُ الافواج فرمائى.', '”اوس خدای پاک ته سوال زاری کوی چې په مونز مهربان شی. ستاسو نه په داسې قربانی پېش کولو، ایا هغه به تاسو قبول کری؟“ مالک خدای رب الافواج فرمایی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Malachi_1_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33163, 'Malachi 1:10', 'Malachi', 1, 10, '”اے کاش چې په تاسو کښې يو کس د عبادتخانې دروازې بندې کړى، نو چې تاسو نور بې‌فائدې اور زما په قربان‌ګاه بل نۀ کړئ. زۀ تاسو نه خوشحاله نۀ يم،“ مالِک خُدائ ربُ الافواج فرمائى، ”او زۀ به ستاسو د لاسونو نه نذرانې قبولې نۀ کړم.', '”اے کاش چې په تاسو کشې یو کس د عبادتخانې دروازې بندې کری، نو چې تاسو نور بې‌فایدې اور زما په قربان‌ګاه بل نۀ کری. زۀ تاسو نه خوشحاله نۀ یم،“ مالک خدای رب الافواج فرمایی، ”او زۀ به ستاسو د لاسونو نه نذرانې قبولې نۀ کرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Malachi_1_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33164, 'Malachi 1:11', 'Malachi', 1, 11, 'زما نوم به د قومونو په مينځ کښې عظيم وى، د نمر راختو نه تر نمر پرېوتو پورې. په هر ځائ کښې به خوشبودارې او پاکې نذرانې ما ته راوړے شى، ځکه چې زما نوم به د قومونو په مينځ کښې عظيم وى،“ مالِک خُدائ ربُ الافواج فرمائى.', 'زما نوم به د قومونو په مینج کشې عظیم وی، د نمر راختو نه تر نمر پرېوتو پورې. په هر جای کشې به خوشبودارې او پاکې نذرانې ما ته راورے شی، جکه چې زما نوم به د قومونو په مینج کشې عظیم وی،“ مالک خدای رب الافواج فرمایی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Malachi_1_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33165, 'Malachi 1:12', 'Malachi', 1, 12, '”خو تاسو زما د نوم بې‌حرمتى کوئ په دې وئيلو سره چې د مالِک خُدائ قربان‌ګاه ناپاکه ده، او د دې خوراک بې‌اهميته دے.', '”خو تاسو زما د نوم بې‌حرمتی کوی په دې وییلو سره چې د مالک خدای قربان‌ګاه ناپاکه ده، او د دې خوراک بې‌اهمیته دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Malachi_1_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33166, 'Malachi 1:13', 'Malachi', 1, 13, 'او تاسو وايئ چې، دا څومره بوج دے. او پوکى وهئ او د دې نه نفرت کوئ،“ مالِک خُدائ ربُ الافواج فرمائى. ”کله چې تاسو د غلا، ګوډ يا بيمار څاروى راولئ او د قربانۍ په طور يې پېش کړئ، آيا زۀ دا ستاسو د لاسونو نه قبول کړم څۀ؟“ مالِک خُدائ فرمائى.', 'او تاسو وایی چې، دا چومره بوج دے. او پوکی وهی او د دې نه نفرت کوی،“ مالک خدای رب الافواج فرمایی. ”کله چې تاسو د غلا، ګود یا بیمار چاروی راولی او د قربانی په طور یې پېش کری، ایا زۀ دا ستاسو د لاسونو نه قبول کرم چۀ؟“ مالک خدای فرمایی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Malachi_1_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33167, 'Malachi 1:14', 'Malachi', 1, 14, '”لعنت دې وى په هغه دوکه باز باندې چې په رمه کښې يې څُرب نر څاروے وى او نذرونه يې منلې وى، خو مالِک ته مات ګوډ څاروے قربانى کړى.“ نو مالِک خُدائ ربُ الافواج فرمائى چې، ”زۀ لوئ بادشاه يم، او په قومونو کښې خلق زما د نوم نه يريږى.“', '”لعنت دې وی په هغه دوکه باز باندې چې په رمه کشې یې چرب نر چاروے وی او نذرونه یې منلې وی، خو مالک ته مات ګود چاروے قربانی کری.“ نو مالک خدای رب الافواج فرمایی چې، ”زۀ لوی بادشاه یم، او په قومونو کشې خلق زما د نوم نه یریزی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Malachi_1_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33168, 'Job 8:1', 'Job', 8, 1, 'بيا بِلداد شوحى ووئيل،', 'بیا بلداد شوحی ووییل،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33169, 'Job 8:2', 'Job', 8, 2, '”ترڅو پورې به تۀ دا خبرې کوې، او دا بک بک به جارى ساتې؟', '”ترچو پورې به تۀ دا خبرې کوې، او دا بک بک به جاری ساتې؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33170, 'Job 8:3', 'Job', 8, 3, 'خُدائ پاک د اِنصاف نه نۀ اوړى. او د قادر خُدائ کارونه همېشه په حقه وى.', 'خدای پاک د انصاف نه نۀ اوری. او د قادر خدای کارونه همېشه په حقه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33171, 'Job 8:4', 'Job', 8, 4, 'کۀ ستاسو بچو د هغۀ خِلاف ګناه کړې وى، نو هغوئ ته به د هغې بدله مِلاو شوې وى.', 'کۀ ستاسو بچو د هغۀ خلاف ګناه کرې وی، نو هغوی ته به د هغې بدله ملاو شوې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33172, 'Job 8:5', 'Job', 8, 5, 'کۀ تۀ خُدائ پاک ولټوې او قادر خُدائ ته په دُعا کښې سوال وکړې،', 'کۀ تۀ خدای پاک ولتوې او قادر خدای ته په دعا کشې سوال وکرې،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33173, 'Job 8:6', 'Job', 8, 6, 'کۀ تۀ صفا او صادق يې، نو هغه به په خپله راپاڅى او هغه به تا له خپل صحيح مقام واپس درکړى.', 'کۀ تۀ صفا او صادق یې، نو هغه به په خپله راپاچی او هغه به تا له خپل صحیح مقام واپس درکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33174, 'Job 8:7', 'Job', 8, 7, 'اګر چې ستا شروع معمولى شان وه، خو په مستقبل کښې به مالدار شې.', 'اګر چې ستا شروع معمولی شان وه، خو په مستقبل کشې به مالدار شې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33175, 'Job 8:8', 'Job', 8, 8, 'معلوماتو دپاره مخکښېنو نسلونو نه تپوس وکړه، او د هغوئ چې کومې تجربې دى په هغې غور وکړه.', 'معلوماتو دپاره مخکشېنو نسلونو نه تپوس وکره، او د هغوی چې کومې تجربې دی په هغې غور وکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33176, 'Job 8:9', 'Job', 8, 9, 'ځکه چې مونږ پرون پېدا شوى يُو او مونږ ته هيڅ پته نۀ لګى، ځکه چې په زمکه باندې زمونږ وخت د سورى په شان روان دے.', 'جکه چې مونز پرون پېدا شوی یو او مونز ته هیچ پته نۀ لګی، جکه چې په زمکه باندې زمونز وخت د سوری په شان روان دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33177, 'Job 8:10', 'Job', 8, 10, 'خو پرېږده چې هوښيار مشران درته ښودنه وکړى، او د هغوئ وېنا ته غوږ نيسه.', 'خو پرېزده چې هوشیار مشران درته شودنه وکری، او د هغوی وېنا ته غوز نیسه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33178, 'Job 8:11', 'Job', 8, 11, 'چرته چې اوبۀ نۀ وى نو هلته لوخه نۀ را شنه کيږى، دا د اوبو نه بغېر نۀ کيږى.', 'چرته چې اوبۀ نۀ وی نو هلته لوخه نۀ را شنه کیزی، دا د اوبو نه بغېر نۀ کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33179, 'Job 8:12', 'Job', 8, 12, 'او دا لا شنه وى او رېبلے شوې نۀ وى، خو د نورو واښو نه زر وچيږى.', 'او دا لا شنه وی او رېبلے شوې نۀ وی، خو د نورو واشو نه زر وچیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33180, 'Job 8:13', 'Job', 8, 13, 'نو چې څوک خُدائ پاک هېروى نو د هغوئ هم دغه لار ده، چې څوک د خُدائ نه منکر وى نو د هغوئ اُميد به ختم شى.', 'نو چې چوک خدای پاک هېروی نو د هغوی هم دغه لار ده، چې چوک د خدای نه منکر وی نو د هغوی امید به ختم شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33181, 'Job 8:14', 'Job', 8, 14, 'د هغوئ ايمان نازک وى، د هغوئ يقين د جولا د جالې په شان وى.', 'د هغوی ایمان نازک وی، د هغوی یقین د جولا د جالې په شان وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33182, 'Job 8:15', 'Job', 8, 15, 'چې څوک په دې جاله يقين کوى نو هغوئ ته به دا جاله ټينګه نۀ شى، کۀ څوک ورپورې ځان وتړى، نو دا به يې برداشت نۀ کړى.', 'چې چوک په دې جاله یقین کوی نو هغوی ته به دا جاله تینګه نۀ شی، کۀ چوک ورپورې جان وتری، نو دا به یې برداشت نۀ کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33183, 'Job 8:16', 'Job', 8, 16, 'منکر کسان داسې ښکارى چې په نمر کښې رازرغون وى، او د دې څانګې په باغ کښې خورې ورې وى.', 'منکر کسان داسې شکاری چې په نمر کشې رازرغون وی، او د دې چانګې په باغ کشې خورې ورې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33184, 'Job 8:17', 'Job', 8, 17, 'د هغوئ جرړې د کاڼو د ډېرى نه تاويږى، او دا کاڼى کلک نيسى.', 'د هغوی جررې د کانو د دېری نه تاویزی، او دا کانی کلک نیسی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33185, 'Job 8:18', 'Job', 8, 18, 'خو کۀ هغوئ د خپل ځائ نه لرې کړے شى، نو بيا به هغوئ اِنکار وکړى او وائى به چې ما تاسو کله هم نۀ يې ليدلے.', 'خو کۀ هغوی د خپل جای نه لرې کرے شی، نو بیا به هغوی انکار وکری او وایی به چې ما تاسو کله هم نۀ یې لیدلے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33186, 'Job 8:19', 'Job', 8, 19, 'ګوره، د هغوئ خوشحالى به د لږ وخت دپاره وى، خو نور بوټى راشنۀ شى او د دې ځائ ونيسى.', 'ګوره، د هغوی خوشحالی به د لز وخت دپاره وی، خو نور بوتی راشنۀ شی او د دې جای ونیسی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33187, 'Job 8:20', 'Job', 8, 20, 'ګوره، خُدائ پاک به يو بې‌داغه کس نۀ رد کوى، او نۀ به د بدعمله خلقو مدد وکړى.', 'ګوره، خدای پاک به یو بې‌داغه کس نۀ رد کوی، او نۀ به د بدعمله خلقو مدد وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_20.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33188, 'Job 8:21', 'Job', 8, 21, 'هغه به بيا هم تاسو له خوشحالى درکړى، او ستاسو خولې به د خندا نۀ ډکې کړى.', 'هغه به بیا هم تاسو له خوشحالی درکری، او ستاسو خولې به د خندا نۀ دکې کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_8_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
